<style scoped lang="scss" src="./timeline.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { differenceInCalendarDays, format, isSameDay } from "date-fns";
import DonatePill from "../../components/donate-pill/donate-pill.vue";
import { CurrencyNotation, CurrencyNotationValues } from "../constants";
import { has } from "../../util/has";

/**
 * It is a component to show the timeline of all the donations for a fund
 */
@Component({
  components: {
    DonatePill
  }
})
export default class Timeline extends Vue {
  @Prop({
    type: Object,
    default: () => ({
      donations: []
    })
  })
  donationBlock;
  @Prop({
    type: String,
    default: CurrencyNotation.USD,
    validator: has(CurrencyNotationValues)
  })
  currency;
  @Prop({
    type: Boolean,
    default: false
  })
  hasMore;
  @Prop({
    type: Boolean,
    default: true
  })
  horizon;

  get blocks() {
    const blocks = [];

    const donations = this.donationBlock.donations.slice();
    if (donations == null || donations.length == 0) return blocks;

    donations.sort((a, b) => b.time - a.time);

    let preDate = donations[0].time;
    blocks.push(preDate);

    for (let i = 0; i < donations.length; i++) {
      const donation = donations[i];

      if (!isSameDay(donation.time, preDate)) {
        preDate = donation.time;
        blocks.push(preDate);
      }

      blocks.push(donation);
    }

    return blocks;
  }

  isDate(item) {
    return item instanceof Date;
  }

  dateString(date) {
    const Today = new Date();
    if (isSameDay(date, Today)) return "Today";
    if (differenceInCalendarDays(date, Today) == -1) return "Yesterday";
    return format(date, "LLLL d");
  }
}
</script>

<template>
  <div :class="['Timeline', this.horizon ? '' : 'Timeline--vertical']">
    <div class="Timeline__Item" v-for="(item, index) of blocks" :key="index">
      <div
        v-if="item.time === undefined"
        :class="{
          Timeline__DateBlock: true,
          'Timeline--first-block': index === 0
        }"
      >
        {{ dateString(item) }}
      </div>
      <div v-else-if="item.showQuote" class="Timeline__PillBlock">
        <div class="Timeline__MiddleLine1" />
        <div class="Timeline__PillContainer">
          <DonatePill
            :name="item.name"
            :time="item.time"
            :amount="item.amount"
            :image="item.image"
            :showQuote="item.showQuote"
            :quote="item.quote"
            :currency="currency"
            :horizon="horizon"
          />
        </div>
        <div
          v-if="index !== blocks.length - 1 || hasMore"
          class="Timeline__MiddleLine2"
        />
      </div>
      <div v-else class="Timeline__PillBlock">
        <div class="Timeline__MiddleLine3" />
        <div
          v-if="index !== blocks.length - 1 || hasMore"
          class="Timeline__MiddleLine4"
        />
        <div class="Timeline__PillContainer">
          <DonatePill
            :name="item.name"
            :time="item.time"
            :amount="item.amount"
            :image="item.image"
            :showQuote="item.showQuote"
            :quote="item.quote"
            :currency="currency"
            :horizon="horizon"
          />
        </div>
      </div>
    </div>
  </div>
</template>
